public void testHeaderBytesRoundTrip() {
    final TarArchiveEntry entry = new TarArchiveEntry("docs/notes.txt");
    entry.setMode(0100640);
    entry.setIds(1000, 100);
    entry.setNames("builder", "staff");
    entry.setSize(4096);
    entry.setModTime(1262304000000L);

    final byte[] header = new byte[512];
    entry.writeEntryHeader(header);

    final TarArchiveEntry copy = new TarArchiveEntry(header);
    assertEquals("docs/notes.txt", copy.getName());
    assertEquals(0100640, copy.getMode());
    assertEquals(1000, copy.getUserId());
    assertEquals(100, copy.getGroupId());
    assertEquals("builder", copy.getUserName());
    assertEquals("staff", copy.getGroupName());
    assertEquals(4096, copy.getSize());
    assertEquals(1262304000000L, copy.getModTime().getTime());
}

